	 (76,'alpha_vantage','WOOF','Pet Acquisition LLC','NASDAQ','USD','USA','CONSUMER CYCLICAL','SPECIALTY RETAIL','Petco Health and Wellness Company, Inc. (WOOF) stands out as a leading specialty retailer committed to improving the health and well-being of pets and their owners through a broad selection of premium products and comprehensive wellness services. Headquartered in San Diego, California, Petco operates a robust network of retail locations and an expanding digital platform, facilitating a seamless and engaging shopping experience. By focusing on innovation and responsible pet ownership, Petco not only addresses the growing demand for pet care solutions but also strengthens its community ties. With a strategic approach to market expansion, the company is well-positioned to capitalize on the burgeoning pet industry, ultimately enhancing shareholder value.','https://corporate.petco.com','January','1826470',711548000,NULL,-0.01,NULL,3.421,'{"CIK": "1826470", "EPS": "-0.01", "Beta": "1.752", "Name": "Pet Acquisition LLC", "EBITDA": "313534000", "Sector": "CONSUMER CYCLICAL", "Symbol": "WOOF", "Address": "10850 VIA FRONTERA, SAN DIEGO, CA, UNITED STATES, 92127", "Country": "USA", "PERatio": "None", "Currency": "USD", "Exchange": "NASDAQ", "Industry": "SPECIALTY RETAIL", "PEGRatio": "None", "52WeekLow": "2.28", "AssetType": "Common Stock", "BookValue": "4.121", "ForwardPE": "8.51", "52WeekHigh": "4.505", "EVToEBITDA": "11.16", "RevenueTTM": "5998469000", "TrailingPE": "-", "Description": "Petco Health and Wellness Company, Inc. (WOOF) stands out as a leading specialty retailer committed to improving the health and well-being of pets and their owners through a broad selection of premium products and comprehensive wellness services. Headquartered in San Diego, California, Petco operates a robust network of retail locations and an expanding digital platform, facilitating a seamless and engaging shopping experience. By focusing on innovation and responsible pet ownershi